<script module lang="ts">
/**
 * Dropzone plus a file list with upload states (`design/components/file-upload.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/file-upload.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import {
  Icon,
  agentMember,
  focusAfterListRemoval,
  formatBytes,
  gateFiles,
  joinSlot,
  watchEffect,
  type FileRejection,
} from '@polymorph/svelte'
import { useListPresence } from '@polymorph/svelte/motion'
import styles from '@polymorph/recipes/controls/file-upload.module.css'
import FileUploadRow from './FileUploadRow.svelte'

export type FileUploadStatus = 'uploading' | 'done' | 'error'

export interface FileUploadItem {
  id: string
  name: string
  size?: number
  status: FileUploadStatus
  progress?: number
  message?: string
}

export interface FileUploadProps {
  /**
   * The native syntax (`.pdf`, `image/*`, `application/pdf`), applied to drops too.
   */
  accept?: string
  'aria-describedby'?: string
  /**
   * Set by FormField. Set it directly only when there is no visible label.
   */
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
  disabled?: boolean
  /**
   * Always controlled, because the list and what happens to it are the app's state.
   */
  files?: FileUploadItem[]
  hint?: string
  invalid?: boolean
  /**
   * The app's size ceiling, in bytes. A file over it never reaches `onFilesAdd`.
   */
  maxSize?: number
  /**
   * All control and announcement text, localized by the application.
   */
  messages?: {
    retry: string
    remove: (name: string) => string
    progress: (name: string) => string
    announcement: (file: FileUploadItem) => string
    formatSize: (bytes: number) => string
  }
  /**
   * When `false`, a drop of several files keeps the first that passes and refuses the rest.
   */
  multiple?: boolean
  /**
   * Set on the hidden picker, for a native form post.
   */
  name?: string
  /**
   * Only files that passed the gate (`accept`, `maxSize`, `multiple`), from the picker or a
   * drop.
   */
  onFilesAdd?: (files: File[]) => void
  /**
   * The counterpart of `onFilesAdd`: every file the gate refused, and why. `file-upload.md`
   * requires a rejection to be "a *visible row*, never a silent drop", and rows only come from
   * `files`, which the app owns. So the component refuses the file and returns it with a reason,
   * and the app renders the refusal as an `error` row in its own words. **Required.** If it were
   * optional, the spec's main guarantee would be optional too. A field that sets `maxSize` and
   * passes no `onReject` would silently drop an oversized file, with no row, no message and no
   * event, and the user would see a chosen file fail to appear. The component cannot write the
   * row itself, because the text and the list belong to the app, and it must not hide the
   * refusal. So the handler is required.
   */
  onReject?: (rejections: FileRejection[]) => void
  onRemove?: (id: string) => void
  /**
   * When supplied, `error` rows offer a retry.
   */
  onRetry?: (id: string) => void
  title?: string
}

export const controlKind = 'group'
</script>

<script lang="ts">
let {
  accept,
  'aria-describedby': ariaDescribedbyOwn,
  'aria-label': ariaLabel,
  'aria-labelledby': ariaLabelledbyOwn,
  'aria-required': ariaRequiredOwn,
  disabled = false,
  files = (() => [])(),
  hint,
  invalid: invalidOwn = false,
  maxSize,
  messages = (() => ({
    retry: 'Retry',
    remove: (name: string) => `Remove ${name}`,
    progress: (name: string) => `${name} upload progress`,
    announcement: (file: FileUploadItem) =>
      file.status === 'done'
        ? `${file.name} uploaded`
        : file.status === 'error'
          ? file.message === undefined
            ? `${file.name} failed`
            : `${file.name} failed: ${file.message}`
          : '',
    formatSize: formatBytes,
  }))(),
  multiple = true,
  name,
  onFilesAdd,
  onReject,
  onRemove,
  onRetry,
  title = 'Drop files or click to browse',
}: FileUploadProps = $props()
const joined = joinSlot(controlKind, () => ({ disabled: disabled, name: name }))
const ariaDescribedby = $derived(
  joined.passed['aria-describedby'] === undefined
    ? ariaDescribedbyOwn
    : (joined.passed['aria-describedby'] as typeof ariaDescribedbyOwn),
)
const ariaLabelledby = $derived(
  joined.passed['aria-labelledby'] === undefined
    ? ariaLabelledbyOwn
    : (joined.passed['aria-labelledby'] as typeof ariaLabelledbyOwn),
)
const ariaRequired = $derived(
  joined.passed['aria-required'] === undefined
    ? ariaRequiredOwn
    : (joined.passed['aria-required'] as typeof ariaRequiredOwn),
)
const invalid = $derived(
  joined.passed['invalid'] === undefined
    ? invalidOwn
    : (joined.passed['invalid'] as typeof invalidOwn),
)
const listening = {
  get filesAdd() {
    return onFilesAdd !== undefined
  },
  get reject() {
    return onReject !== undefined
  },
  get remove() {
    return onRemove !== undefined
  },
  get retry() {
    return onRetry !== undefined
  },
}
let dragover = $state(false)
let pressed = $state(null as { id: string; at: number } | null)
let picker = $state<HTMLElement | null>(null)
let root = $state<HTMLElement | null>(null)
let rowList = $state<HTMLElement | null>(null)
let zone = $state<HTMLElement | null>(null)
const zoneState = $derived(dragover ? 'dragover' : 'idle')
const rowOf = $derived((id: string | undefined) =>
  id === undefined
    ? null
    : (rowList?.children[rows.current.findIndex((row) => row.key === id)] ?? null),
)
const removeControl = $derived((row: Element | null) =>
  row === null ? null : ([...row.querySelectorAll<HTMLElement>('button')].pop() ?? null),
)
const add = $derived(
  (list: FileList | null | undefined) =>
    !disabled &&
    list != null &&
    list.length > 0 &&
    ((gate) => (
      gate.accepted.length > 0 && onFilesAdd?.(gate.accepted),
      gate.rejected.length > 0 && onReject?.(gate.rejected)
    ))(gateFiles(Array.from(list), { accept, multiple, maxSize })),
)
const rows = useListPresence(
  () => files,
  (file: FileUploadItem) => file.id,
)
const effect1 = () => {
  pressed = focusAfterListRemoval(
    pressed,
    files.map((file) => file.id),
    (at) => removeControl(rowOf(files[at]?.id)),
    zone,
    pressed === null ? null : rowOf(pressed.id),
  )
}
watchEffect(effect1, { watch: () => files, mount: false })
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const ran = agentMember({
    member: 'FileUpload',
    element: () => zone,
    state: () => ({
      files: files.map((file) => ({ ...file })),
      rows: files.map((file) => ({ id: file.id, label: file.name })),
      disabled: disabled,
      invalid: invalid,
    }),
    actions: {
      remove: { argument: 'id', run: (value) => onRemove?.(value) },
      retry: {
        argument: 'id',
        run: (value) =>
          (() => {
            if (listening.retry !== true) throw new Error('The field offers no retry.')
            if (files.find((file) => file.id === value)?.status !== 'error')
              throw new Error('Only a failed upload is retried.')
            onRetry?.(value)
          })(),
      },
    },
    withholds: () => root,
  })
  release2 = () => {
    ran()
  }
}
watchEffect(effect2)
onDestroy(() => release2?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div
    bind:this={root}
    class={styles.root}
    data-state={zoneState}
    data-disabled={(disabled) ? '' : undefined}
    data-invalid={(invalid) ? '' : undefined}
    data-member="file-upload"
    ><button
      bind:this={zone}
      class={styles.zone}
      type="button"
      {disabled}
      data-state={zoneState}
      data-disabled={(disabled) ? '' : undefined}
      data-invalid={(invalid) ? '' : undefined}
      aria-label={ariaLabel}
      aria-labelledby={ariaLabelledby}
      aria-describedby={ariaDescribedby}
      aria-required={ariaRequired}
      aria-invalid={(invalid) ? true : undefined}
      onclick={() => { picker?.click() }}
      ondragover={(event) => { (event.preventDefault(), !disabled && (dragover = true)) }}
      ondragleave={(event) => { if (!(event.currentTarget as HTMLElement).contains(event.relatedTarget as Node | null)) (dragover = false) }}
      ondrop={(event) => { (event.preventDefault(), (dragover = false), add(event.dataTransfer?.files)) }}
      ><Icon name="upload" size="lg"
      /><span class={styles.title}>{title}</span
      >{#if hint !== undefined}<span class={styles.hint}>{hint}</span>{/if
    }</button
    ><input
      bind:this={picker}
      class={styles.picker}
      type="file"
      {accept}
      {multiple}
      {name}
      {disabled}
      tabindex="-1"
      onchange={(event) => { (add((event.target as HTMLInputElement).files), ((event.target as HTMLInputElement).value = '')) }}
    />{#if files.length > 0
      }<ul bind:this={rowList} class={styles.list}
        >{#each rows.current as row (row.key)
          }<FileUploadRow
            file={row.item}
            open={row.open}
            size={row.item.size === undefined ? undefined : messages.formatSize(row.item.size)}
            retryable={listening.retry === true}
            {disabled}
            retryLabel={messages.retry}
            removeLabel={messages.remove(row.item.name)}
            progressLabel={messages.progress(row.item.name)}
            onRetry={() => { onRetry?.(row.item.id) }}
            onRemove={() => { ((pressed = { id: row.item.id, at: files.findIndex((file) => file.id === row.item.id) }), onRemove?.(row.item.id)) }}
            onDone={() => { row.done() }}
        />{/each
      }</ul
    >{/if
    }<span class={styles.reader} aria-live="polite"
      >{#each files as file (file.id)}<span>{messages.announcement(file)}</span>{/each
    }</span
  ></div
>{/if
}{@render joined.end?.()}
